fn add_list(arr1: &Vec<i32>, arr2: &Vec<i32>) -> Vec<i32> {
    // Since the arrays are guaranteed to have the same length,
    // we can zip their iterators and sum the pairs element-wise.
    arr1.iter()
        .zip(arr2.iter())
        .map(|(a, b)| a + b)
        .collect()
}